/**
 * @method
 * @name scwin.setPeriod
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.setPeriod = function (str) {
    /* sdd-asis-lifecycle:begin setPeriod — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.clearBtnImage();
    if (str === '01') {
        noticeIframe.location.href = "/help/01.htm";
        $c.util.getComponent("m01").src = "/img/main/pop_month_01_selected.gif";
    } else {
        if (str === '02') {
            noticeIframe.location.href = "/help/02.htm";
            $c.util.getComponent("m02").src = "/img/main/pop_month_02_selected.gif";
        } else {
            if (str === '03') {
                noticeIframe.location.href = "/help/03.htm";
                $c.util.getComponent("m03").src = "/img/main/pop_month_03_selected.gif";
            } else {
                if (str === '04') {
                    noticeIframe.location.href = "/help/04.htm";
                    $c.util.getComponent("m04").src = "/img/main/pop_month_04_selected.gif";
                } else {
                    if (str === '05') {
                        noticeIframe.location.href = "/help/05.htm";
                        $c.util.getComponent("m05").src = "/img/main/pop_month_05_selected.gif";
                    } else {
                        if (str === '06') {
                            noticeIframe.location.href = "/help/06.htm";
                            $c.util.getComponent("m06").src = "/img/main/pop_month_06_selected.gif";
                        } else {
                            if (str === '07') {
                                noticeIframe.location.href = "/help/07.htm";
                                $c.util.getComponent("m07").src = "/img/main/pop_month_07_selected.gif";
                            } else {
                                if (str === '08') {
                                    noticeIframe.location.href = "/help/08.htm";
                                    $c.util.getComponent("m08").src = "/img/main/pop_month_08_selected.gif";
                                } else {
                                    if (str === '09') {
                                        noticeIframe.location.href = "/help/09.htm";
                                        $c.util.getComponent("m09").src = "/img/main/pop_month_09_selected.gif";
                                    } else {
                                        if (str === '10') {
                                            noticeIframe.location.href = "/help/10.htm";
                                            $c.util.getComponent("m10").src = "/img/main/pop_month_10_selected.gif";
                                        } else {
                                            if (str === '11') {
                                                noticeIframe.location.href = "/help/11.htm";
                                                $c.util.getComponent("m11").src = "/img/main/pop_month_11_selected.gif";
                                            } else {
                                                if (str === '12') {
                                                    noticeIframe.location.href = "/help/12.htm";
                                                    $c.util.getComponent("m12").src = "/img/main/pop_month_12_selected.gif";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
